  onRemoveOffPrice(): void {

    if (!this.cart.isOffCodeUsed) {

      SharedIonic.toast(this.toastController, 'کد تخفیفی درج نشده است');
      return;
    }

    SharedIonic.loading(this.loadingController);

    this.orderService.RemoveOffPrice().subscribe(

      res => {
        SharedIonic.dismissLoading(this.loadingController);

        if (res.status === GResponse.SuccessStatus) {

          this.cart.isOffCodeUsed = false;
          this.cart.usedOffCodePercent = 0;
          this.cart.usedOffCodePrice = 0;

          if (this.cart.isProductOffCode) {
            this.productsPrice = this.getProductsPrice();
          } else {
            this.totalOffPrice = this.getTotalOffPrice();
          }

          this.totalPayPrice = this.getTotalPayPrice();
          SharedIonic.toast(this.toastController, 'کد تخفیف حذف شد');
        } else if (res.status === GResponse.AccessDeniedStatus) {

          SharedIonic.toast(this.toastController, 'کد تخفیف حذف نشد');
        } else {
          SharedIonic.toast(this.toastController, 'کد تخفیف حذف نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

