import { PageHeaderModule } from 'src/app/view/components/app/page-header/page-header.module';
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';

import { CartRoutingModule } from './cart-routing.module';
import { CartComponent } from './cart.component';
import { IonicModule } from '@ionic/angular';

import { FooterModule } from '../../components/app/footer/footer.module';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { PersianDateModule } from 'src/app/core/pipe/persian-date/persian-date.module';
import { PriceModule } from 'src/app/core/pipe/price.module';
import { AccountInterceptor } from '../../../core/utility/account.interceptor';
import { OrderService } from '../../../data/service/order/order.service';
import { LoadingModule } from '../../components/common/loading/loading.module';


@NgModule({
  declarations: [CartComponent],
  imports: [
    PageHeaderModule,
    CommonModule,
    CartRoutingModule,
    IonicModule,
    
    FooterModule,
    FormsModule,
    PriceModule,
    PersianDateModule,
    ReactiveFormsModule,
    HttpClientModule,
    LoadingModule
  ],
  providers: [
    OrderService,
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AccountInterceptor,
      multi: true
    }
  ]
})
export class CartModule { }
